css:
/* From Uiverse.io by ahmed150up - Tags: form, chat */
.__UIV_SCOPE__ .card {
  width: 260px;
  background-color: #fff;
  border: 1px solid #ccc;
  border-radius: 5px;
  box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .chat-header {
  background-color: #333;
  color: #fff;
  padding: 10px;
  font-size: 18px;
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
}

.__UIV_SCOPE__ .chat-window {
  height: 220px;
  overflow-y: scroll;
}

.__UIV_SCOPE__ .message-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.__UIV_SCOPE__ .chat-input {
  display: flex;
  align-items: center;
  padding: 10px;
  border-top: 1px solid #ccc;
}

.__UIV_SCOPE__ .message-input {
  flex: 1;
  border: none;
  outline: none;
  padding: 5px;
  font-size: 14px;
}

.__UIV_SCOPE__ .send-button {
  border: none;
  outline: none;
  background-color: #333;
  color: #fff;
  font-size: 14px;
  padding: 5px 10px;
  cursor: pointer;
}

.__UIV_SCOPE__ .send-button:hover {
  background-color: rgb(255, 255, 255);
  color: rgb(0, 0, 0);
  box-shadow: 0 4px 18px 0 rgba(0, 0, 0, 0.25);
}
